<?php
$rooms = $pdo->query(
    "SELECT rooms.*, (SELECT COUNT(*) FROM allocations WHERE allocations.room_id = rooms.id AND allocations.status = 'Active') AS occupied
     FROM rooms ORDER BY building, room_number"
)->fetchAll();
$editingRoom = null;
if (in_array($role, ['admin', 'warden'], true) && isset($_GET['edit'])) {
    $editQuery = $pdo->prepare('SELECT * FROM rooms WHERE id = ?');
    $editQuery->execute([(int) $_GET['edit']]);
    $editingRoom = $editQuery->fetch() ?: null;
}
?>
<section class="page-heading-row"><div><span class="eyebrow">A PLACE TO CALL HOME</span><h1>Hostel rooms<span class="heading-dot">.</span></h1><p>Room details, occupancy, and availability at a glance.</p></div><span class="count-chip"><?= count($rooms) ?> rooms</span></section>
<?php if (in_array($role, ['admin', 'warden'], true)): ?><section class="panel form-panel"><div class="panel-heading"><div><span class="eyebrow">HOSTEL DIRECTORY</span><h2><?= $editingRoom ? 'Edit room details' : 'Add a room' ?></h2></div><span class="form-step">01 <i>/</i> room details</span></div>
<form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= $editingRoom ? 'update_room' : 'save_room' ?>"><input type="hidden" name="return_to" value="rooms"><?php if ($editingRoom): ?><input type="hidden" name="room_id" value="<?= (int) $editingRoom['id'] ?>"><?php endif; ?>
<label class="form-field"><span>Room number</span><input name="room_number" required maxlength="30" placeholder="e.g. C-108" value="<?= e($editingRoom['room_number'] ?? '') ?>"></label><label class="form-field"><span>Building / hostel</span><input name="building" required maxlength="100" placeholder="e.g. Maple House" value="<?= e($editingRoom['building'] ?? '') ?>"></label><label class="form-field"><span>Capacity</span><input name="capacity" type="number" min="1" max="100" required placeholder="e.g. 3" value="<?= e($editingRoom['capacity'] ?? '') ?>"></label><label class="form-field"><span>Room status</span><select name="status"><?php foreach (['Active', 'Maintenance', 'Inactive'] as $status): ?><option <?= ($editingRoom['status'] ?? 'Active') === $status ? 'selected' : '' ?>><?= e($status) ?></option><?php endforeach; ?></select></label><div class="form-submit-row"><span>Occupied rooms cannot be made unavailable or reduced below occupancy.</span><button class="button button-primary" type="submit"><?= $editingRoom ? 'Save changes' : 'Add room' ?> <span>→</span></button><?php if ($editingRoom): ?><a class="text-link" href="index.php?view=rooms">Cancel</a><?php endif; ?></div></form></section><?php endif; ?>
<section class="room-grid"><?php foreach ($rooms as $room): $available = (int) $room['capacity'] - (int) $room['occupied']; ?><article class="room-card <?= $room['status'] !== 'Active' ? 'room-card-muted' : '' ?>"><div class="room-card-top"><span class="room-building"><?= e($room['building']) ?></span><span class="room-status room-status-<?= strtolower(e($room['status'])) ?>"><i></i><?= e($room['status']) ?></span></div><div class="room-number">Room <b><?= e($room['room_number']) ?></b></div><div class="occupancy-row"><div><b><?= (int) $room['occupied'] ?></b><span> / <?= (int) $room['capacity'] ?> occupied</span></div><span><?= $available > 0 && $room['status'] === 'Active' ? $available . ' available' : 'At capacity' ?></span></div><div class="occupancy-track"><span style="width: <?= (int) min(100, round(((int) $room['occupied'] / max(1, (int) $room['capacity'])) * 100)) ?>%"></span></div><div class="room-card-bottom"><span><?= $room['status'] === 'Active' && $available > 0 ? '✦ Ready for allocation' : ($room['status'] === 'Active' ? 'Room is full' : 'Unavailable for allocation') ?></span><?php if (in_array($role, ['admin', 'warden'], true)): ?><a href="index.php?view=rooms&amp;edit=<?= (int) $room['id'] ?>" aria-label="Edit room <?= e($room['room_number']) ?>">Edit</a><?php else: ?><a href="index.php?view=allocations" aria-label="View allocations">↗</a><?php endif; ?></div></article><?php endforeach; ?>
<?php if (!$rooms): ?><div class="panel empty-state"><span class="empty-art">⌂</span><b>No rooms in the directory</b><p>Add a room to start managing hostel capacity.</p></div><?php endif; ?></section>
